import pytest
from log_analyzer.core import fetch_all

def test_two_pages_in_order():
    calls=[]
    def fetch(cursor):
        calls.append(cursor);return {'items':[1,2],'next':'p2'} if cursor is None else {'items':[3],'next':None}
