def test_empty_terminal():assert fetch_all(lambda c:{'items':[],'next':None})==[]
def test_bounded_timeout_retry():
    calls=[]
    def fetch(c):
        calls.append(c)
        if len(calls)<3:raise TimeoutError('simulated')
        return {'items':[1],'next':None}
    assert fetch_all(fetch,retries=2)==[1] and len(calls)==3

def test_failure_not_partial_success():
    calls=[]
    def fetch(c):
        calls.append(c)
        if c is not None:raise TimeoutError('simulated')
        return {'items':[1],'next':'next'}
    with pytest.raises(TimeoutError):fetch_all(fetch,retries=1)
    assert calls==[None,'next','next']
