from html.parser import HTMLParser
from log_analyzer.core import render_html

class Inspect(HTMLParser):
    def __init__(self):super().__init__();self.tags=[];self.attrs=[];self.data=[]
    def handle_starttag(self,tag,attrs):self.tags.append(tag);self.attrs.extend(attrs)
    def handle_data(self,data):self.data.append(data)

def parse(s):p=Inspect();p.feed(s);return p

def test_full_document_and_headers():
    p=parse(render_html([]));assert 'html' in p.tags and 'title' in p.tags and 'table' in p.tags
    text=' '.join(p.data).lower();assert all(x in text for x in ['account','count','ips','event ids'])
def test_escaped_untrusted_labels():
    name='<script>alert(1)</script>';p=parse(render_html([{'id':'<img src=x>','account':name,'at':'2026-01-01T00:00:00Z','ip':'<b>ip</b>'}]))
    assert 'script' not in p.tags and 'img' not in p.tags and name in ''.join(p.data)
